{
  "$schema": "https://pets.studio/config.json",
  "name": "@openpets/huggingface",
  "version": "1.0.0",
  "title": "HuggingFace",
  "subtitle": "Access HuggingFace Hub and Inference APIs",
  "description": "Comprehensive OpenPets plugin for HuggingFace providing full access to the HuggingFace Hub and Inference APIs. Search models and datasets, manage repositories, upload files, and run various inference tasks including text generation, image generation, and audio transcription.",
  "homepage": "https://huggingface.co",
  "categories": [
    "ai",
    "machine-learning",
    "developer-tools"
  ],
  "main": "index.ts",
  "types": "index.ts",
  "keywords": [
    "opencode",
    "plugin",
    "huggingface",
    "ai",
    "machine-learning",
    "llm",
    "inference",
    "models"
  ],
  "envVariables": {
    "required": [
      {
        "name": "HUGGINGFACE_API_KEY",
        "description": "HuggingFace access token from https://huggingface.co/settings/tokens",
        "provider": "HuggingFace",
        "priority": 1
      }
    ],
    "optional": [
      {
        "name": "HUGGINGFACE_INFERENCE_PROVIDER",
        "description": "Default inference provider (auto, sambanova, together, fal-ai, replicate, cohere)",
        "provider": "HuggingFace",
        "priority": 2
      },
      {
        "name": "HUGGINGFACE_ENABLE_TEXT_INFERENCE",
        "description": "Enable text inference module (true/false)",
        "provider": "HuggingFace",
        "priority": 3
      },
      {
        "name": "HUGGINGFACE_ENABLE_IMAGE_INFERENCE",
        "description": "Enable image inference module (true/false)",
        "provider": "HuggingFace",
        "priority": 4
      },
      {
        "name": "HUGGINGFACE_ENABLE_AUDIO_INFERENCE",
        "description": "Enable audio inference module (true/false)",
        "provider": "HuggingFace",
        "priority": 5
      }
    ]
  },
  "queries": [
    "test my huggingface connection",
    "search for text generation models",
    "list models by meta-llama",
    "get details for meta-llama/Llama-3.1-8B-Instruct",
    "generate text with gpt2 using prompt 'Once upon a time'",
    "translate 'Hello, how are you?' to French",
    "create a new model repository called my-awesome-model"
  ],
  "scenarios": {
    "model-search": [
      "test my huggingface connection",
      "search for text generation models",
      "get details for meta-llama/Llama-3.1-8B-Instruct"
    ],
    "text-generation": [
      "test my huggingface connection",
      "generate text with gpt2 using prompt 'Once upon a time'",
      "chat completion with meta-llama/Llama-3.1-8B-Instruct: What is machine learning?"
    ],
    "repository-management": [
      "test my huggingface connection",
      "create a new model repository called my-awesome-model",
      "upload README.md with content 'My Model' to my-awesome-model"
    ]
  },
  "faq": [
    {
      "question": "How do I get my HuggingFace API key?",
      "answer": "Go to https://huggingface.co/settings/tokens and create a new access token with appropriate permissions: Read for listing models/datasets and running inference, Write for creating repos and uploading files."
    },
    {
      "question": "How do I enable inference modules?",
      "answer": "Set environment variables: HUGGINGFACE_ENABLE_TEXT_INFERENCE=true, HUGGINGFACE_ENABLE_IMAGE_INFERENCE=true, and/or HUGGINGFACE_ENABLE_AUDIO_INFERENCE=true. All inference modules are disabled by default."
    },
    {
      "question": "What models are supported?",
      "answer": "You can use any publicly available model on HuggingFace Hub, or private models your token has access to. Popular models include meta-llama/Llama-3.1-8B-Instruct, stabilityai/stable-diffusion-2, and openai/whisper-large-v3."
    },
    {
      "question": "Why am I getting rate limit errors?",
      "answer": "HuggingFace has rate limits on the free tier. Consider using a paid plan or reducing request frequency. Some models may also have longer loading times - retry after a few seconds."
    }
  ],
  "scripts": {
    "build": "pets build",
    "quickstart": "opencode run \"test my huggingface connection\"",
    "test:connection": "opencode run \"test my huggingface connection\"",
    "test:search": "opencode run \"search for text generation models\""
  },
  "dependencies": {
    "dotenv": "^16.0.0",
    "@huggingface/inference": "^2.0.0",
    "@huggingface/hub": "^0.5.0"
  },
  "publishConfig": {
    "access": "public"
  },
  "files": [
    "index.ts",
    "index.js",
    "client.ts",
    "client.js",
    "*.d.ts",
    "lib/**/*",
    "src/**/*",
    "commands.json",
    "public/**/*",
    "prompts/**/*",
    "README.md"
  ]
}
